import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';
import { CartSummary } from './CartSummary';
import { CartProvider } from '../state/CartContext';
import type { CartState } from '@/types/cart';

function renderWithProvider(initialState: CartState) {
  return render(
    <CartProvider initialState={initialState}>
      <CartSummary />
    </CartProvider>
  );
}

describe('CartSummary', () => {
  it('renderiza mensagem de carrinho vazio', () => {
    renderWithProvider({ items: [], couponCode: null });

    expect(screen.getByText('Seu carrinho está vazio.')).toBeInTheDocument();
  });

  it('renderiza itens do carrinho', () => {
    const initialState = {
      items: [
        { id: '1', name: 'Produto A', price: 100, quantity: 2 },
        { id: '2', name: 'Produto B', price: 50, quantity: 1 },
      ],
      couponCode: null,
    };
    renderWithProvider(initialState);

    const items = screen.getAllByRole('listitem');
    expect(items).toHaveLength(2);
    expect(items[0]).toHaveTextContent('Produto A × 2');
    expect(items[0]).toHaveTextContent('R$ 200,00');
    expect(items[1]).toHaveTextContent('Produto B × 1');
    expect(items[1]).toHaveTextContent('R$ 50,00');
  });

  it('aplica cupom válido', async () => {
    const initialState = {
      items: [
        { id: '1', name: 'Produto A', price: 100, quantity: 2 },
      ],
      couponCode: null,
    };
    const user = userEvent.setup();
    renderWithProvider(initialState);

    await user.type(screen.getByLabelText('Cupom de desconto'), 'PROMO10');
    await user.click(screen.getByRole('button', { name: 'Aplicar' }));

    expect(screen.getByText('Cupom PROMO10 aplicado.')).toBeInTheDocument();
  });

  it('exibe erro para cupom inválido', async () => {
    const initialState = {
      items: [
        { id: '1', name: 'Produto A', price: 100, quantity: 2 },
      ],
      couponCode: null,
    };
    const user = userEvent.setup();
    renderWithProvider(initialState);

    await user.type(screen.getByLabelText('Cupom de desconto'), 'INVALIDO');
    await user.click(screen.getByRole('button', { name: 'Aplicar' }));

    expect(screen.getByRole('alert')).toHaveTextContent('Cupom inválido.');
  });

  it('remove item do carrinho', async () => {
    const initialState = {
      items: [
        { id: '1', name: 'Produto A', price: 100, quantity: 2 },
        { id: '2', name: 'Produto B', price: 50, quantity: 1 },
      ],
      couponCode: null,
    };
    const user = userEvent.setup();
    renderWithProvider(initialState);

    await user.click(screen.getByRole('button', { name: 'Remover Produto A' }));

    const items = screen.getAllByRole('listitem');
    expect(items).toHaveLength(1);
    expect(items[0]).toHaveTextContent('Produto B × 1');
  });

  it('remove cupom aplicado', async () => {
    const initialState = {
      items: [
        { id: '1', name: 'Produto A', price: 100, quantity: 2 },
      ],
      couponCode: 'PROMO10',
    };
    const user = userEvent.setup();
    renderWithProvider(initialState);

    await user.click(screen.getByRole('button', { name: 'Remover cupom' }));

    expect(screen.getByLabelText('Cupom de desconto')).toBeInTheDocument();
  });

  it('esvazia o carrinho', async () => {
    const initialState = {
      items: [
        { id: '1', name: 'Produto A', price: 100, quantity: 2 },
        { id: '2', name: 'Produto B', price: 50, quantity: 1 },
      ],
      couponCode: null,
    };
    const user = userEvent.setup();
    renderWithProvider(initialState);

    await user.click(screen.getByRole('button', { name: 'Esvaziar carrinho' }));

    expect(screen.getByText('Seu carrinho está vazio.')).toBeInTheDocument();
  });

  it('calcula subtotal, desconto e total corretamente', () => {
    const initialState = {
      items: [
        { id: '1', name: 'Produto A', price: 100, quantity: 2 },
        { id: '2', name: 'Produto B', price: 50, quantity: 1 },
      ],
      couponCode: 'PROMO10',
    };
    renderWithProvider(initialState);

    expect(screen.getByTestId('subtotal')).toHaveTextContent('R$ 250,00');
    expect(screen.getByTestId('discount')).toHaveTextContent('-R$ 25,00');
    expect(screen.getByTestId('total')).toHaveTextContent('R$ 225,00');
  });

  it('renderiza corretamente com cupom não aplicado', () => {
    const initialState = {
      items: [
        { id: '1', name: 'Produto A', price: 100, quantity: 2 },
      ],
      couponCode: null,
    };
    renderWithProvider(initialState);

    expect(screen.getByLabelText('Cupom de desconto')).toBeInTheDocument();
  });
});

